from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
import binascii

def try_decrypt(keygen_func, key_desc):
    # Read enc file
    with open('flag.enc', 'rb') as f:
        ciphertext = f.read()
    iv = b'r4nd0m_1v_ch053n'
    key = bytes(keygen_func(i) for i in range(32))
    cipher = AES.new(key, AES.MODE_CBC, iv)
    decrypted = cipher.decrypt(ciphertext)
    try:
        dec_unpadded = unpad(decrypted, 16)
    except ValueError as e:
        dec_unpadded = b""  # Padding error = bad key
    print(f'--- {key_desc} ---')
    print(f'Key: {binascii.hexlify(key).decode()}')
    print("First 128 bytes (hex):", binascii.hexlify(decrypted[:128]))
    print("First 128 bytes (utf-8):", decrypted[:128].decode('utf-8','replace'))
    flag_idx = dec_unpadded.find(b'csawctf{')
    if flag_idx != -1:
        flag_end = dec_unpadded.find(b'}', flag_idx)
        if flag_end != -1:
            print("[!] Flag Found:", dec_unpadded[flag_idx:flag_end+1].decode('utf-8','replace'))
        else:
            print("Possible flag start:", dec_unpadded[flag_idx:flag_idx+80])
    else:
        print("No flag pattern found in unpadded output.")
    print()

