from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
import binascii
import codecs

IV = b'r4nd0m_1v_ch053n'
ENC_PATH = '/home/ctfplayer/ctf_files/flag.enc'

def try_decrypt(key):
    with open(ENC_PATH, 'rb') as f:
        encrypted = f.read()
    cipher = AES.new(key, AES.MODE_CBC, IV)
    try:
        pt = unpad(cipher.decrypt(encrypted), AES.block_size)
    except Exception as e:
        print(f"Decryption failed ({e})")
        return None
    return pt

def key_variant1():
    return bytes([pow(2, i, 256) for i in range(32)])

def key_variant2():
    return bytes([pow(2, i % 8) for i in range(32)])

def print_info(kname, key, result):
    print(f'--- Trying {kname} ---')
    print(f'KEY hex: {binascii.hexlify(key).decode()}')
    if result:
        hexp = binascii.hexlify(result[:128])
        try:
            utxt = result[:128].decode("utf-8",errors="replace")
        except:
            utxt = "<err>"
        print(f"First 128 bytes - hex:\n{hexp}")
        print(f"First 128 bytes - utf-8:\n{utxt}\n")
        if b'csawctf{' in result:
            flag = result[result.index(b'csawctf{'):]
            try:
                flag_txt = flag.decode("utf-8")
                print("FLAG FOUND! Result:\n"+flag_txt)
            except:
                print("FLAG bytes: ", repr(flag[:64]))
        else:
            print("NO FLAG FOUND in this key.\n")
    else:
        print("NO DECRYPTED OUTPUT.\n")

def main():
    key1 = key_variant1()
    res1 = try_decrypt(key1)
    print_info("KEY #1", key1, res1)
    key2 = key_variant2()
    res2 = try_decrypt(key2)
    print_info("KEY #2", key2, res2)

if __name__ == "__main__":
    main()
